contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        // ensure the caller is not blacklisted and distribution is not finished
        require(c.blacklist(address(this)) == false);
        require(c.distributionFinished() == false);

        uint256 beforeValue = c.value();
        uint256 beforeRemaining = c.totalRemaining();
        require(beforeValue <= beforeRemaining);

        bool reverted;
        try c.getTokens() { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            uint256 afterValue = c.value();
            assert(afterValue == beforeValue - (beforeValue / 100000));
        } else {
            assert(c.value() == beforeValue);
        }
    }
}

